create table acquisition (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, description varchar(255), name varchar(255) not null, primary key (id));
create table asset_categories (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_type_id uuid not null, id uuid not null, description varchar(255), name varchar(255) not null, primary key (id));
create table asset_document_types (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, name varchar(255) not null, primary key (id));
create table asset_documents (uploaded_at timestamp(6) with time zone not null, asset_id uuid not null, document_type_id uuid not null, id uuid not null, caption varchar(255), document_url varchar(255) not null, primary key (id));
create table asset_images (is_primary boolean not null, uploaded_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, caption varchar(255), image_url varchar(255) not null, primary key (id));
create table asset_types (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, description varchar(255), name varchar(255) not null, primary key (id));
create table assets (created_at timestamp(6) with time zone not null, deleted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, asset_category_id uuid not null, id uuid not null, user_id uuid not null, description varchar(255), primary key (id));
create table bank_accounts (bank_account_number integer not null, currency varchar(3) not null, current_balance numeric(19,2) not null, interest_rate numeric(5,2), previous_balance numeric(19,2) not null, created_at timestamp(6) with time zone not null, current_balance_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, bank varchar(255) not null, primary key (id));
create table cash_assets (bank_account_number integer not null, currency varchar(3) not null, current_value numeric(19,2) not null, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, primary key (id));
create table collectibles_valuables (currency varchar(3) not null, current_value numeric(19,2) not null, year integer, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, creator varchar(255), material varchar(255), serial_number varchar(255), primary key (id));
create table electronics (currency varchar(3) not null, current_value numeric(19,2) not null, year integer, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, brand varchar(255) not null, color varchar(255), model varchar(255), serial_number varchar(255), primary key (id));
create table furniture (currency varchar(3) not null, current_value numeric(19,2) not null, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, brand varchar(255), description varchar(255), material varchar(255), primary key (id));
create table insurance (coverage_amount numeric(19,2) not null, currency varchar(3) not null, end_date date not null, premium_amount numeric(19,2) not null, start_date date not null, coverage_amount_updated_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, premium_frequency varchar(255) not null, provider varchar(255) not null, primary key (id));
create table investments (currency varchar(3) not null, current_value numeric(19,2) not null, interest_rate numeric(5,2), quantity integer, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, institution varchar(255), reference_number varchar(255), primary key (id));
create table land (currency varchar(3) not null, current_value numeric(19,2) not null, land_size integer not null, land_size_unit varchar(3) not null, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, address varchar(255) not null, description varchar(255), plot_number varchar(255) not null, primary key (id));
create table loans (amount_owed numeric(19,2) not null, currency varchar(3) not null, due_date date not null, interest_rate numeric(5,2), maturity_date date, original_amount numeric(19,2) not null, outstanding_balance numeric(19,2) not null, start_date date not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, creditor varchar(255) not null, description varchar(255), lender varchar(255) not null, primary key (id));
create table machinery (currency varchar(3) not null, current_value numeric(19,2) not null, year integer, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, brand varchar(255), material varchar(255), model varchar(255), primary key (id));
create table miscellaneous (currency varchar(3) not null, current_value numeric(19,2) not null, year integer, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, brand varchar(255), description varchar(255), material varchar(255), model varchar(255), serial_number varchar(255), primary key (id));
create table real_estate (construction_completion_date date, construction_cost numeric(19,2), construction_currency varchar(3), currency varchar(3) not null, current_value numeric(19,2) not null, number_bathrooms integer, number_bedrooms integer, number_units integer, property_size integer, property_size_unit varchar(3), rental_income numeric(16,2), rental_income_currency varchar(3), created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, address varchar(255) not null, description varchar(255), primary key (id));
create table retirement_funds (currency varchar(3) not null, current_value numeric(19,2) not null, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, provider varchar(255) not null, primary key (id));
create table savings (currency varchar(3) not null, current_balance numeric(19,2) not null, interest_rate numeric(5,2), maturity_date date, created_at timestamp(6) with time zone not null, current_balance_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, account_number varchar(255) not null, institution varchar(255) not null, primary key (id));
create table stock_assets (number_shares integer not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, brokerage varchar(255) not null, ticker_symbol varchar(255) not null, primary key (id));
create table users (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, email varchar(255) not null, first_name varchar(255) not null, gender varchar(255) not null check ((gender in ('MALE','FEMALE'))), last_name varchar(255) not null, password varchar(255) not null, phone_number varchar(255), primary key (id));
create table vehicles (currency varchar(3) not null, current_value numeric(19,2) not null, mileage integer, year integer not null, created_at timestamp(6) with time zone not null, current_value_updated_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, asset_id uuid not null, id uuid not null, color varchar(255) not null, make varchar(255) not null, model varchar(255) not null, registration_number varchar(255), vin varchar(255), primary key (id));
